UPDATE TBLMI_WORK_HST
SET UPD_ID = #{upd_id}
	,UPD_DT = now()
	,WORK_END_DT = now()

	,work_stat = #{work_stat}


	,work_msg = #{work_msg}


	seq = #{seq}

mapper.select:
select count(*)
from tblmi_work_hst as wrk
	INNER JOIN tblmi_usr AS usr
			ON wrk.work_usr_id = usr.usr_id


		wrk.seq = #{seq}


		and wrk.work_grp_cd = #{work_grp_cd}


		and wrk.work_usr_ip = #{work_usr_ip}


		and wrk.work_type LIKE CONCAT('%',#{work_type},'%')


		and wrk.work_stat = #{work_stat}


		and usr.usr_email LIKE CONCAT('%',#{usr_email},'%')

SELECT wrk.seq, wrk.work_type, usr.usr_email AS work_usr_id, wrk.work_usr_ip, wrk.work_stat, wrk.work_msg, wrk.work_grp_cd, wrk.notify, wrk.work_st_dt, wrk.work_end_dt, wrk.reg_id, wrk.reg_dt, wrk.upd_id, wrk.upd_dt FROM tblmi_work_hst AS wrk INNER JOIN tblmi_usr AS usr ON wrk.work_usr_id = usr.usr_id
wrk.seq = #{seq}
and wrk.work_grp_cd = #{work_grp_cd}
and wrk.work_usr_ip = #{work_usr_ip}
and wrk.work_type LIKE CONCAT('%',#{work_type},'%')
and wrk.work_stat LIKE CONCAT('%',#{work_stat},'%')
and usr.usr_email LIKE CONCAT('%',#{usr_email},'%')
order by REG_DT DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

SELECT *
FROM tblmi_work_hst a

	NOT EXISTS (
			SELECT 1
			FROM tblmi_work_hst b
			WHERE work_stat = '3'
			and a.seq = b.seq
	)

		AND a.work_usr_id = #{work_usr_id}


		AND a.work_grp_cd = #{work_grp_cd}



			and (a.REG_DT >= #{reg_dt} and a.REG_DT  <  #{reg_dt_range})



		AND a.notify = #{notify}

		ORDER BY a.reg_dt desc

		LIMIT #{isLimit}

